import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse('{"title":"术语速查表","description":"","frontmatter":{},"headers":[],"relativePath":"zh/appendix/glossary.md","filePath":"zh/appendix/glossary.md"}'),h={name:"zh/appendix/glossary.md"};function n(i,a,l,d,s,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="术语速查表" tabindex="-1">术语速查表 <a class="header-anchor" href="#术语速查表" aria-label="Permalink to &quot;术语速查表&quot;">​</a></h1><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="agent-智能体" tabindex="-1">Agent（智能体） <a class="header-anchor" href="#agent-智能体" aria-label="Permalink to &quot;Agent（智能体）&quot;">​</a></h3><p>AI 系统的一种形态，能够自主感知环境、做出决策并执行行动。Codex 就是一个 AI 编程智能体——它能&quot;读文件、写代码、运行命令&quot;，而不是被动回答问题。</p><h3 id="api-应用程序接口" tabindex="-1">API（应用程序接口） <a class="header-anchor" href="#api-应用程序接口" aria-label="Permalink to &quot;API（应用程序接口）&quot;">​</a></h3><p>不同软件之间通信的规则和协议。比如 Codex 通过 API 与 OpenAI 的服务器通信，获取 AI 能力。</p><hr><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="cli-命令行界面" tabindex="-1">CLI（命令行界面） <a class="header-anchor" href="#cli-命令行界面" aria-label="Permalink to &quot;CLI（命令行界面）&quot;">​</a></h3><p>Command Line Interface 的缩写。通过输入文本命令来操作电脑的方式，与图形界面（点鼠标）相对。Codex 有 CLI 版本，适合高级用户使用。</p><h3 id="code-interpreter-代码解释器" tabindex="-1">Code Interpreter（代码解释器） <a class="header-anchor" href="#code-interpreter-代码解释器" aria-label="Permalink to &quot;Code Interpreter（代码解释器）&quot;">​</a></h3><p>ChatGPT 的一个功能，可以让 AI 运行你上传的代码并返回结果。Codex 桌面 App 的核心能力之一就是代码解释器的增强版。</p><hr><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="deep-learning-深度学习" tabindex="-1">Deep Learning（深度学习） <a class="header-anchor" href="#deep-learning-深度学习" aria-label="Permalink to &quot;Deep Learning（深度学习）&quot;">​</a></h3><p>机器学习的一个分支，使用多层神经网络来学习数据中的复杂模式。Codex 背后的技术基础就是深度学习。</p><hr><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><p>全球最大的代码托管平台，开发者在上面分享、协作和管理代码项目。</p><hr><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="llm-大语言模型" tabindex="-1">LLM（大语言模型） <a class="header-anchor" href="#llm-大语言模型" aria-label="Permalink to &quot;LLM（大语言模型）&quot;">​</a></h3><p>Large Language Model 的缩写，指参数量巨大的语言模型。ChatGPT、Codex 等都基于 LLM 技术。</p><h3 id="local-storage-本地存储" tabindex="-1">Local Storage（本地存储） <a class="header-anchor" href="#local-storage-本地存储" aria-label="Permalink to &quot;Local Storage（本地存储）&quot;">​</a></h3><p>浏览器提供的一种数据存储方式，网页可以在用户的浏览器中保存数据，即使关闭页面也不会丢失。项目三中用到的待办事项持久化就依赖它。</p><hr><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h3><p>一种轻量级标记语言，用简单的文本符号来表示格式（如标题用 <code>#</code>，加粗用 <code>**</code>）。GitBook 使用 Markdown 作为内容格式。</p><h3 id="mcp-model-context-protocol" tabindex="-1">MCP（Model Context Protocol） <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP（Model Context Protocol）&quot;">​</a></h3><p>模型上下文协议，一种让 AI 模型连接外部工具和数据的标准化协议。通过 MCP，Codex 可以访问更多外部资源。</p><h3 id="machine-learning-机器学习" tabindex="-1">Machine Learning（机器学习） <a class="header-anchor" href="#machine-learning-机器学习" aria-label="Permalink to &quot;Machine Learning（机器学习）&quot;">​</a></h3><p>人工智能的一个分支，让计算机从数据中学习规律，而不需要显式编程。</p><hr><h2 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h2><h3 id="natural-language-processing-nlp-自然语言处理" tabindex="-1">Natural Language Processing（NLP，自然语言处理） <a class="header-anchor" href="#natural-language-processing-nlp-自然语言处理" aria-label="Permalink to &quot;Natural Language Processing（NLP，自然语言处理）&quot;">​</a></h3><p>让计算机理解和生成人类语言的技术。Codex 能听懂你的中文指令，靠的就是 NLP 技术。</p><hr><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="prompt-提示词-指令" tabindex="-1">Prompt（提示词/指令） <a class="header-anchor" href="#prompt-提示词-指令" aria-label="Permalink to &quot;Prompt（提示词/指令）&quot;">​</a></h3><p>你输入给 AI 的文字指令。好的 prompt 能得到更好的结果。课程中多次强调&quot;写好指令&quot;的重要性。</p><h3 id="python" tabindex="-1">Python <a class="header-anchor" href="#python" aria-label="Permalink to &quot;Python&quot;">​</a></h3><p>一种广泛使用的编程语言，语法简洁易读，非常适合数据处理、自动化脚本等任务。Codex 生成的代码很多是 Python。</p><hr><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="rpa-机器人流程自动化" tabindex="-1">RPA（机器人流程自动化） <a class="header-anchor" href="#rpa-机器人流程自动化" aria-label="Permalink to &quot;RPA（机器人流程自动化）&quot;">​</a></h3><p>用软件机器人自动执行重复性任务的技術。Codex 可以看作是 RPA 的升级版——它更灵活，不需要预先设计好流程。</p><hr><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="sandbox-沙盒" tabindex="-1">Sandbox（沙盒） <a class="header-anchor" href="#sandbox-沙盒" aria-label="Permalink to &quot;Sandbox（沙盒）&quot;">​</a></h3><p>一种隔离执行的环境。Codex 的工作区就是一种&quot;沙盒&quot;——它只能在工作区内操作文件，不会影响其他区域。</p><h3 id="session-会话" tabindex="-1">Session（会话） <a class="header-anchor" href="#session-会话" aria-label="Permalink to &quot;Session（会话）&quot;">​</a></h3><p>一次对话的完整过程。从你打开 Codex 开始输入第一条消息，到关闭应用为止，就是一个会话。</p><hr><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="vibe-coding-氛围编程" tabindex="-1">Vibe Coding（氛围编程） <a class="header-anchor" href="#vibe-coding-氛围编程" aria-label="Permalink to &quot;Vibe Coding（氛围编程）&quot;">​</a></h3><p>一种新的编程理念：不写代码，而是用自然语言描述你想要的效果，让 AI 来完成实现。本课程的核心教学理念就是 Vibe Coding。</p><hr><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="workspace-工作区" tabindex="-1">Workspace（工作区） <a class="header-anchor" href="#workspace-工作区" aria-label="Permalink to &quot;Workspace（工作区）&quot;">​</a></h3><p>Codex 中最重要的概念之一。工作区是你指定给 AI 的文件操作范围，类似一个&quot;安全沙盒&quot;。</p><hr><h2 id="📝-使用提示" tabindex="-1">📝 使用提示 <a class="header-anchor" href="#📝-使用提示" aria-label="Permalink to &quot;📝 使用提示&quot;">​</a></h2><ul><li>本术语表使用大白话解释，避免技术黑话</li><li>如果某个术语在文中多次出现但仍有疑问，随时回查本表</li><li>术语会随技术发展而更新，最新版本请参考 <a href="https://help.openai.com" target="_blank" rel="noreferrer">OpenAI 官方文档</a></li></ul>',66)])])}const b=e(h,[["render",n]]);export{u as __pageData,b as default};
